video = options.createVideo();
initializing = Promise.resolve(video.initialize());
await initializing;
initialized = true;
if (cancelled) return;
// The native setter caches the handle before its bridge call, which can throw after mutation.
surfaceAttached = true;
video.setSurfaceHandle(options.handle);
options.installPolyfills(video);
player = options.createPlayer();
removePlayerObservers = options.observePlayer?.(player, () => !cancelled) ?? null;
controller = options.createController(player, () => !cancelled);
controller.setTimeShiftEnabled(options.getTimeShiftEnabled());
options.controllerRef.current = controller;
await player.load(options.source);

export function createVegaPlayer(config: PlayerConfig): PlayerAPI {
  registerVegaPlayerModules();
  return new Player(undefined as unknown as HTMLElement, vegaPlayerConfig(config));
}

player: {
  playback: { autoplay: draft.autoplay, muted: draft.muted },
  ...(video !== undefined || audio !== undefined ? { buffer: {
    ...(video !== undefined ? { video: { forwardduration: video } } : {}),
    ...(audio !== undefined ? { audio: { forwardduration: audio } } : {}),
  } } : {}),
  ...(maxVideoBitrate !== undefined ? { adaptation: { bitrates: { maxSelectableVideoBitrate: maxVideoBitrate } } } : {}),
},

export function vegaPlayerConfig(config: PlayerConfig): PlayerConfig {
  // Vega's media integration supports Fetch rather than the SDK's default XHR.
  return { ...config, network: { ...config.network, requestApi: NetworkRequestApi.Fetch } };
}

{lifecycle.active && <KeplerVideoSurfaceView key={lifecycle.generation}
  testID="vega-video-surface" style={styles.surface} scalingmode="fit"
  onSurfaceViewCreated={(handle: string) => {
    const current = lifecycleRef.current;
    if (current.active && current.generation === lifecycle.generation) setSurfaceHandle(handle);
  }} />}
{subtitleText !== "" && <View pointerEvents="none" style={styles.captions}>
  <Text testID="vega-subtitle-cue" style={styles.cue}>{subtitleText}</Text>
</View>}

player.on(PlayerEvent.CueEnter, enter);
player.on(PlayerEvent.CueExit, exit);
player.on(PlayerEvent.SubtitleDisabled, clear);

const config = useMemo<PlayerConfig>(
  () => ({
    key: LICENSE_KEY,
    ui: false,
    ...applied.player,
    tweaks: { app_id: "com.playerlab.vega" },
    // §15: the analytics module is registered in vegaPlayer.ts; the collector
    // only activates when a key is configured here.
    ...(ANALYTICS_LICENSE_KEY ? { analytics: { key: ANALYTICS_LICENSE_KEY } } : {}),
  }),
  [applied.player],
);
